import pandas as pd
import matplotlib.pyplot as plt

# Read CSV generated by C program
df = pd.read_csv("student_results.csv")

print("\n=== Student Results Table ===")
print(df)

# Bar Chart: Average comparison
plt.figure(figsize=(8,5))
plt.bar(df['Student'], df['Average'])
plt.title("Average Marks Comparison")
plt.xlabel("Students")
plt.ylabel("Average Marks")
plt.show()

# Pie Chart: Grade distribution
plt.figure(figsize=(6,5))
grade_count = df['Grade'].value_counts()
plt.pie(grade_count, labels=grade_count.index, autopct='%1.1f%%')
plt.title("Grade Distribution")
plt.show()

# Highest & Lowest performers
highest = df.loc[df['Average'].idxmax()]
lowest = df.loc[df['Average'].idxmin()]

print("\n🏆 Top Performer:")
print(highest)

print("\n📉 Lowest Performer:")
print(lowest)